cd /workspace/project && python3 -c "
import ast, sys, pathlib
for p in sorted(pathlib.Path('.').rglob('*.py')):
    tree = ast.parse(p.read_text())
    src = p.read_text()
    imported = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            for a in node.names:
                imported[a.asname or a.name] = node.lineno
        elif isinstance(node, ast.Import):
            for a in node.names:
                name = (a.asname or a.name).split('.')[0]
                imported[name] = node.lineno
    used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)} | \
           {n.attr for n in ast.walk(tree) if isinstance(n, ast.Attribute)} | \
           {n.value.id for n in ast.walk(tree) if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name)}
    # names used inside string annotations / attribute bases
    for name, line in sorted(imported.items(), key=lambda kv: kv[1]):
        if name not in used and name not in src.split('__all__')[0]:
            if src.count(name) <= 1:
                print('%s:%d unused import %s' % (p, line, name))
"
